const referenceReview=`<section id="writing-reference-review" hidden><div class="reference-review-heading"><div><span class="capabilities-kicker">STEP 03 · VERIFY SOURCES</span><h2>参考文献确认</h2><p>${isStructured?`检索推荐文献、在线搜索或导入文献，用于支撑${kindLabel}内容。`:'检索推荐文献、在线搜索或导入文献，确认后用于论文提纲与正文引用。'}</p></div><span class="reference-selection-count" id="writing-reference-count">已选 0 篇</span></div><div class="reference-source-grid"><button type="button" class="reference-source-card is-active" data-reference-mode="recommend"><span class="reference-source-icon">✦</span><span><b>推荐文献</b><small>按题目与关键词，在线检索相关参考文献</small></span><span class="reference-source-arrow">→</span></button><button type="button" class="reference-source-card" data-reference-mode="import"><span class="reference-source-icon">↥</span><span><b>导入文献</b><small>导入 JSON 记录或 DOCX / PDF / TXT 文献</small></span><span class="reference-source-arrow">→</span></button><button type="button" class="reference-source-card" data-reference-mode="search"><span class="reference-source-icon">⌕</span><span><b>搜索文献</b><small>按题目、关键词或 DOI 查找相关文献</small></span><span class="reference-source-arrow">→</span></button></div><div class="reference-search-panel" id="writing-reference-search-panel" hidden><label for="writing-reference-query">筛选本次参考文献</label><div class="reference-search-input"><span aria-hidden="true">⌕</span><input id="writing-reference-query" type="search" placeholder="输入题目、作者、DOI 或关键词"><button type="button" class="btn secondary" id="writing-reference-search-clear">清空</button></div><small>这里只筛选本次已选文献；添加新的文献，请点击上方“搜索文献”。</small></div><input id="writing-reference-file" type="file" accept=".json,.docx,.pdf,.txt" hidden><p class="reference-status" id="writing-reference-status" role="status"></p><div id="writing-reference-list" class="reference-list"></div>${taskKind==='writing'?'<p class="reference-footnote">研究资料上传可选。文献含摘要时，可展开后采用摘要；也可导入有权使用的文献正文。仅有题录可以先确认并生成提纲，正文生成前会再检查可用参考内容。</p>':''}<div class="reference-actions"><button class="btn secondary" type="button" id="writing-reference-back">← 返回精准知识补充</button><button class="btn primary" type="button" id="writing-reference-confirm">${isStructured?`确认文献，进入${kindLabel}提纲确认 →`:'确认文献，进入论文提纲确认 →'}</button></div><p class="reference-footnote">${isStructured?`文献仅在确认后加入当前${kindLabel}草稿。`:'文献仅在确认后加入当前论文草稿。'}请核对作者、年份、来源与 DOI，确保引用真实可追溯。</p></section>`;
document.querySelector('.dashboard').innerHTML=`${writingDetailHeading(taskKind)}<main class="writing-focus-main">${['writing','proposal','summary','taskbook','article','course','practice','topic','questionnaire','analysis','quick'].includes(taskKind)?workflowGuide(taskKind):''}<div class="creation-grid"><section class="card creation-input"><h2>基础信息填写</h2><p class="section-hint">先填写论文基本信息，后续步骤可继续补充知识与材料。</p><div class="creation-actions"><button type="button" class="btn secondary" id="writing-save">保存草稿</button><button type="button" class="btn primary" id="writing-generate">下一步：精准知识补充 <span aria-hidden="true">→</span></button></div><p class="creation-disclaimer">${taskKind==='writing'?'前四步确认研究信息、资料与提纲；第五步保存到账户，确认费用后再由 AI 分章生成。':'当前生成本地结构模板，AI 服务尚未接入；材料仅解析，不自动用于生成。'}</p><form id="writing-form"><label for="writing-project">所属项目（可选）</label><select id="writing-project" data-project-picker data-project-ref="${esc(loaded?.projectId||projectId||'')}">${projectPickerOptions(loaded?.projectId||projectId||'')}</select><label for="writing-language">写作语言</label><select id="writing-language"><option value="中文" ${loaded?.language!=='英文'?'selected':''}>中文</option><option value="英文" ${loaded?.language==='英文'?'selected':''}>${taskKind==='writing'?'英文（生成后需自行核对）':'英文（手动编辑；不自动翻译）'}</option></select><div class="creation-row"><div><label for="writing-degree">学历层次</label><select id="writing-degree">${['专科','本科','硕士','博士','科研人员'].map(d=>`<option ${d===initialDegree?'selected':''}>${d}</option>`).join('')}</select></div><div><label for="writing-major">${isStructured?'研究方向':taskKind==='writing'?'学科专业（可选）':'学科专业'}</label><input id="writing-major" maxlength="${taskKind==='writing'?200:100}" value="${esc(initialMajor)}" placeholder="${taskKind==='writing'?'例如：教育学、计算机科学与技术；暂不确定可跳过':'例如：教育学'}"></div></div>${taskKind==='writing'?`<details class="thesis-profile-fields writing-research-options" id="writing-research-options" open><summary><span><b>研究问题与方法（可选） <em>可稍后填写</em></b><small>暂不确定可跳过，后续也能补充</small></span><span class="writing-research-toggle" aria-hidden="true"></span></summary><div class="writing-research-body"><p id="writing-research-hint">按你已经了解的内容填写即可；不清楚的先留空，后续可结合开题报告、导师要求或研究资料补充。</p><label for="writing-direction">研究方向（可选）</label><input id="writing-direction" maxlength="1000" value="${esc(loaded?.direction||'')}" placeholder="例如：人工智能辅助教学；暂不确定可不填" aria-describedby="writing-research-hint"><label for="writing-research-question">核心研究问题（可选）</label><textarea id="writing-research-question" rows="3" maxlength="3000" placeholder="你希望通过这篇论文弄清楚什么？可以用自己的话描述，也可以先留空。">${esc(loaded?.researchQuestion||'')}</textarea><label for="writing-method">研究方法或论证路径（可选）</label><textarea id="writing-method" rows="2" maxlength="1000" placeholder="如已确定，可填写文献分析、访谈、案例研究或实验设计；不确定可先跳过。">${esc(loaded?.method||'')}</textarea><small>留空不会阻止进入下一步。在线生成前仍需确认真实研究材料，实验、问卷与统计结果请以实际资料为准。</small></div></details>`:''}${isPractice?`<div class="creation-row practice-basic-fields"><div><label for="practice-unit">实践单位</label><input id="practice-unit" maxlength="120" value="${esc(loaded?.practiceUnit||'')}" placeholder="例如：XX教育科技有限公司"></div><div><label for="practice-position">实践岗位</label><input id="practice-position" maxlength="80" value="${esc(loaded?.practicePosition||'')}" placeholder="例如：课程助理"></div></div><div class="creation-row practice-basic-fields"><div><label for="practice-start">开始日期</label><input id="practice-start" type="date" value="${esc(loaded?.practiceStart||'')}"></div><div><label for="practice-end">结束日期</label><input id="practice-end" type="date" value="${esc(loaded?.practiceEnd||'')}"></div></div>`:''}${isTopic?`<div class="topic-basic-fields"><label for="topic-direction">研究方向</label><input id="topic-direction" maxlength=160 value="${esc(loaded?.topicDirection||'')}" placeholder="例如：人工智能在教育中的应用"><label for="topic-question">研究问题</label><textarea id="topic-question" rows="3" maxlength="2000" placeholder="描述希望解决的核心问题、对象与范围…">${esc(loaded?.topicQuestion||'')}</textarea><label for="topic-method">研究方法与成果形式</label><input id="topic-method" maxlength="200" value="${esc(loaded?.topicMethod||'')}" placeholder="例如：案例研究；形成研究报告或论文"></div>`:''}${isQuestionnaire?`<div class="questionnaire-basic-fields"><label for="questionnaire-goal">研究目标</label><textarea id="questionnaire-goal" rows="3" maxlength="2000" placeholder="说明问卷要回答的研究问题和使用场景…">${esc(loaded?.questionnaireGoal||'')}</textarea><div class="creation-row"><div><label for="questionnaire-group">目标群体</label><select id="questionnaire-group"><option value="学生" ${loaded?.questionnaireGroup==='学生'?'selected':''}>学生</option><option value="教师" ${loaded?.questionnaireGroup==='教师'?'selected':''}>教师</option><option value="职场人群" ${loaded?.questionnaireGroup==='职场人群'?'selected':''}>职场人群</option><option value="其他" ${loaded?.questionnaireGroup==='其他'?'selected':''}>其他</option></select></div><div><label for="questionnaire-count">题目数量</label><select id="questionnaire-count"><option value="15-25" ${loaded?.questionnaireCount==='15-25'?'selected':''}>简短版（15–25题）</option><option value="25-40" ${loaded?.questionnaireCount==='25-40'?'selected':''}>标准版（25–40题）</option><option value="40-60" ${loaded?.questionnaireCount==='40-60'?'selected':''}>详细版（40–60题）</option></select></div></div><label for="questionnaire-dimensions">测量维度</label><input id="questionnaire-dimensions" maxlength="500" value="${esc(loaded?.questionnaireDimensions||'')}" placeholder="例如：认知、态度、行为意向"></div>`:''}${isAnalysis?`<div class="analysis-basic-fields"><label for="analysis-question">研究目的与问题</label><textarea id="analysis-question" rows="3" maxlength="3000" placeholder="说明希望通过数据分析回答的研究问题…">${esc(loaded?.analysisQuestion||'')}</textarea><label for="analysis-variables">变量与数据来源</label><textarea id="analysis-variables" rows="3" maxlength="3000" placeholder="列出核心变量、样本量、数据来源与数据格式…">${esc(loaded?.analysisVariables||'')}</textarea><label for="analysis-expected">探索性分析结果 <small>（可选）</small></label><textarea id="analysis-expected" rows="2" maxlength="1500" placeholder="粘贴已有的描述统计、趋势观察或初步发现，并注明使用的工具…">${esc(loaded?.analysisExpected||'')}</textarea><label for="analysis-method">预期分析方法</label><textarea id="analysis-method" rows="2" maxlength="1500" placeholder="例如：描述统计、相关分析、回归分析、可视化…">${esc(loaded?.analysisMethod||'')}</textarea><label for="analysis-file">数据附件（可选）</label><input id="analysis-file" type="file" accept=".csv,.xlsx,.xls"><small class="field-note" id="analysis-file-status">${analysisFileName?`已选择：${esc(analysisFileName)}`:'支持 CSV / XLSX / XLS；当前仅记录文件名'}</small><p class="field-note">当前仅记录分析计划与文件名，不执行统计计算；请勿上传未经授权的敏感数据。</p></div>`:''}${isQuick?`<div class="quick-basic-fields"><label for="quick-keywords">关键词</label><input id="quick-keywords" maxlength="200" value="${esc(loaded?.quickKeywords||'')}" placeholder="例如：人工智能、学习反馈、教育评价（用顿号分隔）"><p class="field-note">输入 3–8 个关键词，帮助快速文章聚焦主题与读者。</p></div>`:''}${isArticle?`<div class="article-basic-fields"><label>投稿类型</label><div class="article-type-cards"><label><input type="radio" name="article-type" value="普通期刊" ${loaded?.articleType!=='中文核心'&&loaded?.articleType!=='SCI期刊'?'checked':''}><span><b>普通期刊</b><small>一般学术期刊投稿</small></span></label><label><input type="radio" name="article-type" value="中文核心" ${loaded?.articleType==='中文核心'?'checked':''}><span><b>中文核心</b><small>较高规范与审稿要求</small></span></label><label><input type="radio" name="article-type" value="SCI期刊" ${loaded?.articleType==='SCI期刊'?'checked':''}><span><b>SCI期刊</b><small>国际期刊投稿准备</small></span></label></div><label for="article-research-type">研究类型</label><select id="article-research-type"><option value="不限" ${loaded?.articleResearchType!=='定量分析'&&loaded?.articleResearchType!=='定性分析'&&loaded?.articleResearchType!=='混合方法'&&loaded?.articleResearchType!=='理论研究'&&loaded?.articleResearchType!=='应用研究'&&loaded?.articleResearchType!=='案例研究'&&loaded?.articleResearchType!=='比较研究'&&loaded?.articleResearchType!=='实验研究'?'selected':''}>不限</option>${['定量分析','定性分析','混合方法','理论研究','应用研究','案例研究','比较研究','实验研究'].map(t=>`<option value="${t}" ${loaded?.articleResearchType===t?'selected':''}>${t}</option>`).join('')}</select></div>`:''}<label for="writing-title">${isQuick?'文章标题':isStructured?kindLabel+'题目':'论文题目'} <span class="writing-required">*</span></label><div class="counted-field"><textarea id="writing-title" required minlength="2" aria-required="true" rows="2" maxlength="200" placeholder="${isQuick?'例如：如何提升远程团队的协作效率':isStructured?`例如：${kindLabel}研究主题`:'例如：人工智能辅助课堂学习反馈的应用研究'}">${esc(loaded?.title??context?.name??'')}</textarea><span id="title-count"></span></div><details class="writing-options" open><summary>${taskKind==='writing'?'字数与内容形式':'字数、图表与公式'} <small>（可选）</small></summary><div class="creation-row"><div><label for="writing-target">目标字数</label><input id="writing-target" type="number" min="500" max="${taskKind==='writing'?80000:100000}" step="${taskKind==='writing'?1:100}" value="${esc(taskKind==='writing'?targetWordsState.targetWords:loaded?.targetWords||'')}" placeholder="例如：8000">${taskKind==='writing'?'<div id="writing-target-suggestions" aria-label="目标字数建议"></div>':''}</div><div><label for="writing-formula">${taskKind==='writing'?'内容形式':'图表与公式'}</label><select id="writing-formula"><option value="text" ${loaded?.formula!=='rich'?'selected':''}>纯文本</option><option value="rich" ${loaded?.formula==='rich'?'selected':''}>${taskKind==='writing'?'数据表、图片、公式与代码':'图表 / 公式 / 代码'}</option></select>${taskKind==='writing'?'<small class="section-hint">在提纲中逐节勾选数据表、图片、公式和代码；勾选后自动启用。未勾选的项目不会主动加入。</small>':''}</div></div></details><details class="writing-material-options" hidden ${fileName?'open':''}><summary>参考材料 <small>（可选）</small></summary><label for="writing-file">${isStructured?'上传研究资料、导师要求或已有草稿':'上传开题报告、导师要求或已有材料'}</label><label class="writing-upload" id="writing-drop" for="writing-file"><span class="upload-symbol" aria-hidden="true">${glyph('upload')}</span><span><b>上传文档或拖拽至此</b><small>TXT / DOCX 最大 50MB；PDF 云解析最大 20MB / 100 页（需登录确认）</small></span><input id="writing-file" type="file" accept=".docx,.pdf,.txt"></label><div id="material-file-card" hidden></div><label class="material-purpose-label" for="material-purpose">材料用途</label><select id="material-purpose">${['参考文献','导师要求','已有草稿','格式要求'].map(n=>`<option ${n===loaded?.materialPurpose?'selected':''}>${n}</option>`).join('')}</select><p class="material-status" id="material-status" role="status"></p><button type="button" id="material-toggle" class="material-toggle" hidden>查看解析正文</button><div id="material-area" hidden><label for="writing-material">解析正文（可核对和编辑）</label><textarea id="writing-material" rows="5" maxlength="20000">${esc(material)}</textarea><button type="button" id="material-remove" class="material-toggle">移除参考材料</button></div></details><div id="writing-error" role="alert" class="error-text"></div></form></section><section class="card creation-output"><div class="task-overview" hidden><h2>当前任务概览</h2><div id="writing-overview"></div></div><section id="writing-material-review" hidden><div class="knowledge-review-heading"><div><span class="capabilities-kicker">STEP 02 · ADD CONTEXT</span><h2>精准知识补充</h2><p>补充研究背景、方法与已有资料，${isStructured?`让后续${kindLabel}结构更贴合你的研究。`:'让后续论文提纲更贴合你的研究。'}</p></div><span class="knowledge-optional">可选步骤</span></div><article class="knowledge-source-card knowledge-ai-card" id="knowledge-ai"><div class="knowledge-card-head"><span class="knowledge-source-icon">✦</span><div><b>AI 补充</b><span class="knowledge-recommended">推荐</span><small>先描述你的研究背景、研究方法或创新点，AI 将据此整理补充建议。</small></div></div><label class="knowledge-ai-label" for="knowledge-ai-input">补充说明</label><textarea id="knowledge-ai-input" rows="4" placeholder="例如：研究对象、核心问题、研究方法、已有结论或需要重点补充的内容…"></textarea><div class="knowledge-ai-actions"><button type="button" class="btn primary" id="knowledge-ai-generate">生成补充建议</button><small class="knowledge-usage">ⓘ 预计使用 1 次 AI 补充额度</small></div><p class="knowledge-inline-status" id="knowledge-ai-status" role="status"></p></article><div class="knowledge-upload-heading"><div><h3>上传研究资料</h3><p>可上传开题报告或其他已有资料，解析后会显示在下方列表。</p></div><span>学校格式模板在最后一步统一设置，无需在此上传</span></div><div class="knowledge-upload-grid"><article class="knowledge-source-card knowledge-upload-card"><div class="knowledge-card-head"><span class="knowledge-source-icon">▤</span><div><b>上传开题报告</b><small>提取研究背景、目标与研究方法</small></div></div><div class="knowledge-dropzone"><span aria-hidden="true">↑</span><small>支持 DOCX / PDF</small><button type="button" class="btn secondary knowledge-upload-trigger" data-purpose="proposal">选择文件</button></div></article><article class="knowledge-source-card knowledge-upload-card"><div class="knowledge-card-head"><span class="knowledge-source-icon">＋</span><div><b>其他资料补充</b><small>上传已有草稿、参考材料或导师要求</small></div></div><div class="knowledge-dropzone"><span aria-hidden="true">↑</span><small>支持 DOCX / PDF / TXT</small><button type="button" class="btn secondary knowledge-upload-trigger" data-purpose="other">选择文件</button></div></article></div><div id="writing-material-summary"></div><button class="btn secondary" type="button" id="writing-open-material" hidden>添加或编辑参考材料</button><div class="knowledge-actions"><button class="btn secondary" type="button" id="writing-save-stage2">保存草稿</button><button class="btn secondary knowledge-skip" type="submit" form="writing-form" id="writing-material-skip">暂不补充</button><button class="btn primary" type="submit" form="writing-form" id="writing-material-confirm">确认补充，进入参考文献确认 →</button></div><p class="knowledge-footnote">补充内容仅用于完善当前论文提纲，可随时删除或跳过；AI 建议请结合真实研究核对。</p></section>${referenceReview}<div class="preview-heading"><h2>论文框架预览</h2><span class="preview-tag" id="preview-tag">${content?'已保存内容':'大纲示例'}</span></div><p class="writing-example-note" id="writing-example-note" hidden></p><div id="writing-outline-area"><details class="outline-source-drawer" id="outline-source-drawer"${taskKind==='writing'||!content?' open':''}><summary><span><b>更换提纲来源</b><small>重新生成、上传或粘贴已有提纲</small></span><i>⌄</i></summary><section class="outline-builder" id="writing-outline-builder"><div class="outline-builder-heading"><div><span class="capabilities-kicker">STEP 04 · CONFIRM OUTLINE</span><h3>${isStructured?`创建${kindLabel}提纲`:'创建论文提纲'}</h3><p>${isStructured?`围绕${kindLabel}的研究目标与内容确认结构。`:(taskKind==='writing'?'根据你的论文题目、研究信息与已确认资料生成专属提纲，也可上传、粘贴已有提纲并自行修改。':'可以让系统生成提纲，也可以上传或粘贴已有提纲，再逐项确认章节结构。')}</p></div><span class="outline-builder-badge">可替换</span></div><div class="outline-source-actions"><button type="button" class="outline-source-card" id="outline-ai-generate"><span class="outline-source-icon">✦</span><span><b>AI 生成提纲</b><small>根据基础信息、精准知识和已确认文献生成结构</small></span><span class="outline-source-arrow">→</span></button><button type="button" class="outline-source-card" id="outline-upload-trigger"><span class="outline-source-icon">↥</span><span><b>上传提纲</b><small>导入 DOCX、PDF 或 TXT 格式的已有提纲</small></span><span class="outline-source-arrow">→</span></button></div>${taskKind==='writing'?`<section id="writing-outline-ai-panel" class="writing-outline-ai-panel" hidden></section>`:''}<input id="outline-file" type="file" accept=".docx,.pdf,.txt" ${taskKind==='writing'?'data-no-file-library':''} hidden><div class="outline-paste"><label for="outline-source-input">粘贴或编辑提纲 <small>（可选）</small></label><textarea id="outline-source-input" rows="5" placeholder="粘贴你的提纲，或在下方逐项新增章节。
标题格式：第一章 你的章节标题；1.1 你的小节标题"></textarea><div class="outline-paste-actions"><span id="outline-builder-status" role="status">请选择一种方式创建或替换提纲。</span><button type="button" class="btn secondary" id="outline-paste-apply">使用这份提纲</button></div></div></section></details><article class="outline-paper" id="outline-paper"></article><textarea id="outline-editor" aria-label="编辑论文大纲" hidden></textarea><div class="creation-actions"><button class="btn secondary outline-stage4-save" id="outline-save-stage4" type="button">保存草稿</button><button class="btn secondary" id="outline-edit">✎　编辑大纲</button><button class="btn secondary" id="outline-export">↓　导出大纲 TXT</button></div>${documentExportButtons('outline')}<p class="writing-next-note">调整并确认提纲后，${isStructured?'可进入生成版本确认。':taskKind==='writing'?'可进入论文撰写与确认，再选择在线生成或本地手动写作。':'可分章节填写正文。'}</p><button type="button" class="btn primary full" id="outline-confirm">${isStructured?'确认提纲，进入版本确认 →':'确认大纲，开始写作 →'}</button></div><section id="writing-body-area" hidden><p class="writing-manual-note">当前为手动填写与本地保存，未调用 AI。请依据真实研究完善${isStructured?kindLabel+'内容':'论文正文'}。</p><label for="body-chapter">章节目录</label><select id="body-chapter"></select><p id="body-retained-note" class="writing-next-note"></p><textarea id="body-editor" rows="15" maxlength="100000" aria-label="编辑章节正文" placeholder="填写当前章节正文…"></textarea><div class="writing-body-count" id="body-count"></div><div class="creation-actions"><button class="btn secondary" id="body-save" type="button">保存正文</button><button class="btn primary" id="body-finish" type="button">编辑与导出 →</button></div></section>${taskKind==='writing'?'<section id="thesis-online-stage" hidden></section>':''}<section id="writing-export-area" hidden><div class="writing-version-header"><div><span class="capabilities-kicker">STEP 05 · CONFIRM VERSION</span><h2>生成版本确认</h2><p>${isStructured?`确认${kindLabel}结构与版本，保存当前版本，后续可返回继续编辑。`:'确认论文结构与版本，保存当前版本，后续可返回继续编辑。'}</p></div><span class="writing-unlock-badge is-locked" id="writing-unlock-badge">未解锁</span></div><div class="writing-version-grid"><article class="writing-version-preview-card"><div class="writing-version-card-head"><div><h3>${isStructured?kindLabel+'提纲预览':'论文大纲预览'}</h3><p>查看已确认的章节结构与字数分配</p></div><span id="writing-version-meta">—</span></div><div class="writing-version-preview" id="writing-version-preview"></div><div class="writing-version-lock" id="writing-version-lock"><span aria-hidden="true">🔒</span><div><b>完整文档导出暂未开放</b><p>可先保存当前版本，保留已填写的内容</p></div></div></article><aside class="writing-version-pay-card"><div class="writing-version-pay-head"><div><span>${isStructured?kindLabel+'生成版':'毕业论文生成版'}</span><b id="writing-version-degree">本科</b></div><span class="writing-version-reference-price">待开放</span></div><h3>文档导出服务</h3><div class="writing-version-options"><button type="button" data-version-plan="basic"><span>基础版</span><strong>未开放</strong><small>结构与正文导出</small></button><button type="button" data-version-plan="advanced" class="is-selected"><span>进阶版</span><strong>未开放</strong><small>完整导出与格式支持</small></button><button type="button" data-version-plan="pro"><span>尊享版</span><strong>未开放</strong><small>扩展支持尚未开放</small></button></div><div class="writing-version-summary" id="writing-version-summary"></div><a class="btn primary full" id="writing-version-recharge" href="#membership/recharge?return=${returnKind}">充值解锁下载 →</a><button type="button" class="btn secondary full" id="writing-version-unlocked" hidden>已解锁，可下载</button><p class="writing-version-payment-note" id="writing-version-payment-note">支付与自动解锁尚未开放。请先保存草稿，已填写内容会继续保留在当前浏览器。</p></aside></div><div class="writing-version-actions"><button class="btn secondary" type="button" id="writing-version-back">${isStructured?'← 返回提纲编辑':'← 返回正文编辑'}</button><button class="btn secondary" type="button" id="writing-version-save">保存当前版本</button></div><div class="writing-version-downloads" id="writing-version-downloads"><span>下载文件</span><button class="btn secondary" type="button" id="body-export">下载 TXT</button>${documentExportButtons('body')}</div><pre id="body-preview" hidden></pre></section><button id="outline-copy" class="material-toggle" hidden>复制大纲全文</button><p id="writing-status" role="status" class="material-status"></p></section></div></main><div class="creation-trust">♧　本地保存 · 请及时导出备份；参考材料在当前浏览器处理，请核对引用来源。</div>`;
decorateWritingDetail(document.querySelector('.dashboard'),taskKind);
const draftHint=document.querySelector('.writing-detail-action-copy small');
if(draftHint&&!hasDraftScope()){draftHint.id='writing-autosave-status';draftHint.setAttribute('role','status');draftHint.textContent=loaded?'已恢复草稿，编辑后自动保存':'草稿会自动保存，随时继续完善';}
const $=s=>document.querySelector(s),alive=()=>$('#writing-form')!==null&&!disposed;
// Preserve unfinished entries separately from the normalized values used by generation.
const draftInputNodes=()=>[...document.querySelectorAll('#writing-form input:not([type="file"])[id],#writing-form textarea[id],#writing-form select[id],#outline-source-input,#knowledge-ai-input,#knowledge-method-input,#material-purpose')].filter(node=>node.id!=='writing-project');
const draftInputs=()=>Object.fromEntries(draftInputNodes().map(node=>[node.id,node.type==='checkbox'||node.type==='radio'?node.checked:node.value]));
