function thesisOutlineProblem(){
 if(!content.trim())return '请先生成、上传或填写论文提纲。';
 ensureOutlineRows();
 if(!outlineRows.length||outlineRows.some(row=>!String(row.title||'').trim()))return '请补全提纲中的章节标题。';
 if(!outlineRows.some(row=>row.level===1&&!isOutlineReferenceTitle(row.title)))return '请至少保留一个正文写作章节。';
 if(outlineRows.filter(row=>row.level===1).length>30)return '论文最多支持 30 个章节，请合并部分章节后继续。';
 let sections=0,units=0;for(let i=0;i<outlineRows.length;i++){const row=outlineRows[i];if(row.level===1)sections=0;else if(++sections>60)return '每章最多支持 60 个小节，请合并部分小节后继续。';const budget=outlineRowBudget(i);if(!budget.readonly)units+=Math.ceil((Number(budget.words)||0)/1800);}
 if(units>120)return '当前提纲超过 120 个生成单元，请合并小节或调整目标字数后继续。';
 if(!validOutlineTarget())return '请设置 500–80,000 的整数目标字数。';
 const short=outlineRows.find((row,index)=>{const budget=outlineRowBudget(index);return !budget.readonly&&(!Number.isSafeInteger(budget.words)||budget.words<20);});
 if(short)return `“${short.title}”至少需要分配 20 字的整数目标，请调整后确认。`;
 if(outlineTotalWords()!==outlineTargetWords())return '提纲字数分配须与目标字数一致，请重新分配后确认。';
 return '';
}
function thesisStepIssue(stage){
 const v=values();
 if(stage>1&&(v.title.length<2||!['专科','本科','硕士','博士','研究工作者','科研人员'].includes(v.degree)||!v.language||!validOutlineTarget()))return {step:1,message:'请先填写有效的论文题目、学位、语言与目标字数。',focus:'#writing-title'};
 if(stage>2){const input=$('#knowledge-ai-input'),parts=splitMethodSupplement(input?.value),recorded=ensureKnowledgeFiles().find(row=>row.kind==='ai');if(parts.invalid)return {step:2,message:methodSupplementRepair,focus:'#knowledge-ai-input'};if(supplementInputInitialized&&input&&parts.userText!==String(recorded?.text||'').trim())return {step:2,message:'研究说明有尚未确认的修改，请在第二步点击“保存补充”或“暂不补充”后继续。',focus:'#knowledge-ai-input'};}
 if(stage>3&&(!writingReferences.length||writingReferences.some(row=>!String(row.title||'').trim()||row.confirmed!==true)))return {step:3,message:'请至少选择 1 篇有效参考文献，并点击“确认文献”后继续。',focus:'#writing-reference-query'};
 if(stage>4){const problem=thesisOutlineProblem();if(problem||!outlineConfirmed||editing)return {step:4,message:problem||'请先核对并确认论文提纲。',focus:'#outline-confirm'};}
 return null;
}
function showThesisStepIssue(issue){
 if(!issue)return;
 const note=$('#writing-step-error');if(note){note.hidden=false;note.textContent=issue.message;}
 if(issue.step===2)$('#material-status').textContent=issue.message;
 if(issue.step===3)$('#writing-reference-status').textContent=issue.message;
 $('#writing-status').textContent=issue.message;
 if(workflowStage===issue.step)$(issue.focus)?.focus({preventScroll:true});
}
function clearThesisStepIssue(){const note=$('#writing-step-error');if(note){note.textContent='';note.hidden=true;}}
function enforceThesisSteps(){
 if(taskKind!=='writing')return;
 const issue=thesisStepIssue(Math.max(workflowStage,workflowUnlockedStage));
 if(!issue)return;
 const wasAhead=workflowStage>issue.step;
 workflowUnlockedStage=Math.min(workflowUnlockedStage,issue.step);workflowStage=Math.min(workflowStage,issue.step);outlineConfirmed=false;manualWriting=false;
 if(wasAhead)showThesisStepIssue({...issue,message:issue.message+' 已保留提纲与已有正文，请补充后继续。'});
}
function requireThesisStep(stage){
 if(taskKind!=='writing')return true;
 const issue=thesisStepIssue(stage);
 if(issue){showThesisStepIssue(issue);return false;}
 if(stage>workflowUnlockedStage+1){showThesisStepIssue({step:workflowUnlockedStage,message:'请先完成当前步骤的确认，再进入下一步。'});return false;}
 clearThesisStepIssue();return true;
}
function navigateWritingStep(stage){
 if(stage===workflowStage||parsing)return;
 if(taskKind==='writing'){
  if(stage>workflowStage&&!requireThesisStep(stage))return;
  if(stage>workflowUnlockedStage||(stage===5&&!outlineConfirmed)){showThesisStepIssue({step:workflowStage,message:'请先完成当前步骤的确认，再进入下一步。'});return;}
  if(workflowStage===5&&!thesisOnlineRouteGuard())return;
 }
 sync();manualWriting=false;editing=false;workflowStage=stage;clearThesisStepIssue();
 if(stage===5)showExport();else render();
}
function advanceWritingStep(stage){if(!requireThesisStep(stage))return false;workflowUnlockedStage=Math.max(workflowUnlockedStage,stage);manualWriting=false;workflowStage=stage;return true;}

let referenceMode='selected',referenceSearchDispose=null;
const referenceId=()=>`writing-ref-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const referenceProviders=new Set(['crossref','europepmc','pubmed','openalex','semantic_scholar','arxiv','aminer']);
const referenceBuckets=new Set(['0','1-10','11-50','51-200','200-1000','201-1000','1000-5000','1001-5000','5000+']);
function referenceBibliographicRecord(row={},provenance=false){
 row=row&&typeof row==='object'&&!Array.isArray(row)?row:{};
 const limits={documentType:40,type:80,journal:500,publisher:500,publicationSource:300,volume:100,issue:100,pages:100,venue:500,accessedAt:100},record=Object.fromEntries(Object.entries(limits).flatMap(([key,max])=>typeof row[key]==='string'?[[key,row[key].slice(0,max)]]:[]));
 if(referenceBuckets.has(row.citationBucket))record.citationBucket=row.citationBucket;
 if(Number.isSafeInteger(row.citationCount)&&row.citationCount>=0){record.citationCount=row.citationCount;if(referenceProviders.has(row.citationCountSource))record.citationCountSource=row.citationCountSource;}
 if(provenance){record.source=row.source;record.sourceId=String(row.sourceId||'').slice(0,200);if(typeof row.doi==='string')record.doi=row.doi.slice(0,300);if(typeof row.year==='string'||typeof row.year==='number')record.year=String(row.year).slice(0,4);if(typeof row.url==='string')record.url=safeReferenceURL(row.url);if(typeof row.fullTextUrl==='string')record.fullTextUrl=safeReferenceURL(row.fullTextUrl);if(typeof row.openAccess==='boolean')record.openAccess=row.openAccess;return record;}
 if(Array.isArray(row.keywords))record.keywords=[...new Set(row.keywords.filter(value=>typeof value==='string').map(value=>value.trim().slice(0,80)).filter(Boolean))].slice(0,20);
 if(Array.isArray(row.authorNames))record.authorNames=row.authorNames.slice(0,100).map(value=>typeof value==='string'?{literal:value}:value).filter(value=>value&&typeof value==='object'&&!Array.isArray(value)).map(value=>Object.fromEntries(['family','given','literal'].flatMap(key=>typeof value[key]==='string'?[[key,value[key].slice(0,200)]]:[]))).filter(value=>Object.keys(value).length);
 if(Array.isArray(row.sourceProvenance))record.sourceProvenance=row.sourceProvenance.slice(0,7).filter(value=>value&&referenceProviders.has(value.source)).map(value=>referenceBibliographicRecord(value,true));
 return record;
}
const normalizeReference=row=>({...referenceBibliographicRecord(row),id:String(row?.id||referenceId()),title:String(row?.title||row?.name||'未命名文献').trim(),authors:String(row?.authors||row?.author||'作者待补充').trim(),year:String(row?.year||'年份待补充'),doi:String(row?.doi||''),url:safeReferenceURL(row?.url),tags:Array.isArray(row?.tags)?row.tags:[],scope:String(row?.scope||'本地文献库'),text:String(row?.text||''),fileName:String(row?.fileName||''),source:row?.source||'local',sourceId:String(row?.sourceId||''),sourceLabel:String(row?.sourceLabel||''),abstract:String(row?.abstract||''),rawCitation:String(row?.rawCitation||''),fullTextUrl:safeReferenceURL(row?.fullTextUrl),fullTextRead:row?.fullTextRead===true,confirmed:row?.confirmed===true,...(typeof row?.openAccess==='boolean'?{openAccess:row.openAccess}:{}),...arxivMetadata(row)});
const referenceKey=row=>{const doi=String(row?.doi||'').trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'').toLowerCase();return doi?'doi:'+doi:String(row?.title||row?.name||'').normalize('NFKC').toLowerCase().replace(/[\p{P}\p{S}\s]+/gu,'')+'|'+String(row?.year||'');};
function referenceCandidates(){const selected=writingReferences.map(normalizeReference);const seen=new Set();return selected.filter(row=>{const key=referenceKey(row);if(seen.has(key))return false;seen.add(key);return true;});}
